    code: "import type { Params, PartsFn, Plugins, Presets } from '@villagekit/design/kit'\nimport { GridBeam } from '@villagekit/part-gridbeam/creator'\nimport { GridPanel } from '@villagekit/part-gridpanel/creator'\n\nexport const parameters = {\n  seatWidth: {\n    label: 'Seat width',\n    shortId: 'sw',\n    type: 'number',\n    min: 20,\n    max: 60,\n    step: 5,\n  },\n  seatDepth: {\n    label: 'Seat depth',\n    shortId: 'sd',\n    type: 'number',\n    min: 5,\n    max: 10,\n    step: 5,\n  },\n  seatHeight: {\n    label: 'Seat height',\n    description: 'The height from the ground to the top of the seat',\n    shortId: 'sh',\n    type: 'number',\n    min: 5,\n    max: 15,\n  },\n  widthOverhang: {\n    label: 'Overhang',\n    description: 'How many grid units should the panel overhang the beams',\n    shortId: 'wo',\n    type: 'number',\n    min: 0,\n    max: 4,\n  },\n  shouldIncludeBack: {\n    label: 'Include back',\n    shortId: 'b',\n    type: 'boolean',\n  },\n  backHeight: {\n    label: 'Back height',\n    description: 'The height from the seat to the top of the backrest',\n    shortId: 'bh',\n    type: 'number',\n    min: 5,\n    max: 10,\n    step: 5,\n  },\n} satisfies Params\n\nexport const presets: Presets<typeof parameters> = [\n  {\n    id: 'regular',\n    label: 'Regular',\n    values: {\n      backHeight: 10,\n      seatDepth: 10,\n      seatHeight: 10,\n      seatWidth: 30,\n      shouldIncludeBack: false,\n      widthOverhang: 3,\n    },\n  },\n  {\n    id: 'regular-with-back',\n    label: 'Regular With Back',\n    values: {\n      backHeight: 10,\n      seatDepth: 10,\n      seatHeight: 10,\n      seatWidth: 30,\n      shouldIncludeBack: true,\n      widthOverhang: 3,\n    },\n  },\n]\n\nexport const plugins: Plugins = ['smart-fasteners']\n\nexport const parts: PartsFn<typeof parameters> = (parameters) => {\n  const { seatWidth, seatDepth, seatHeight, backHeight, widthOverhang, shouldIncludeBack } =\n    parameters\n\n  const backZBeamEndZ = shouldIncludeBack ? seatHeight + backHeight : seatHeight\n  const seatPanelStartY = shouldIncludeBack ? -1 : 0\n  const seatPanelEndY = shouldIncludeBack ? seatDepth - 1 : seatDepth\n\n  // 0-30 => 0, 31-45 => 1, 46-60 => 2\n  const numLegSupports = Math.ceil((seatWidth - 30) / 15)\n\n  return [\n    GridPanel.XY({\n      x: [0, seatWidth],\n      y: [seatPanelStartY, seatPanelEndY],\n      z: seatHeight,\n    }),\n\n    shouldIncludeBack &&\n      GridPanel.XZ({\n        x: [0, seatWidth],\n        y: seatDepth - 2,\n        z: [seatHeight + 1, seatHeight + 1 + backHeight],\n        fit: 'top',\n      }),\n\n    GridBeam.Z({\n      x: widthOverhang,\n      y: 0,\n      z: [0, seatHeight],\n    }),\n    GridBeam.Z({\n      x: seatWidth - 1 - widthOverhang,\n      y: 0,\n      z: [0, seatHeight],\n    }),\n    GridBeam.Z({\n      x: widthOverhang,\n      y: seatDepth - 1,\n      z: [0, backZBeamEndZ],\n    }),\n    GridBeam.Z({\n      x: seatWidth - 1 - widthOverhang,\n      y: seatDepth - 1,\n      z: [0, backZBeamEndZ],\n    }),\n\n    GridBeam.X({\n      x: [0, seatWidth],\n      y: 1,\n      z: seatHeight - 1,\n    }),\n    GridBeam.X({\n      x: [0, seatWidth],\n      y: seatDepth - 2,\n      z: seatHeight - 1,\n    }),\n\n    GridBeam.Y({\n      x: 1 + widthOverhang,\n      y: [0, seatDepth],\n      z: seatHeight - 2,\n    }),\n    GridBeam.Y({\n      x: seatWidth - 2 - widthOverhang,\n      y: [0, seatDepth],\n      z: seatHeight - 2,\n    }),\n\n    range(numLegSupports).map((legSupportIndex) => {\n      const legSupportOffsetMultiplier = 1 / (numLegSupports + 1)\n      const legSupportOffset =\n        Math.round(legSupportOffsetMultiplier * seatWidth * (legSupportIndex + 1)) - 1\n      // nudge z posts towards the middle\n      const legZSupportXNudge = legSupportIndex >= Math.floor(numLegSupports / 2) ? -1 : 1\n\n      return [\n        GridBeam.Y({\n          x: legSupportOffset + legZSupportXNudge,\n          y: [0, seatDepth],\n          z: seatHeight - 2,\n        }),\n        GridBeam.Z({\n          x: legSupportOffset,\n          y: 0,\n          z: [0, backZBeamEndZ],\n        }),\n        GridBeam.Z({\n          x: legSupportOffset,\n          y: seatDepth - 1,\n          z: [0, seatHeight],\n        }),\n      ]\n    }),\n  ]\n}\n\nfunction range(end: number) {\n  return Array.from(Array(end).keys())\n}\n",
