    code: "import type { Params, Parts, PartsFn, Plugins, Presets } from '@villagekit/design/kit'\nimport { GridBeam } from '@villagekit/part-gridbeam/creator'\nimport { GridPanel } from '@villagekit/part-gridpanel/creator'\n\nexport const parameters = {\n  treeHeight: {\n    label: 'Tree height',\n    shortId: 'th',\n    type: 'number',\n    min: 20,\n    max: 60,\n    step: 10,\n  },\n  branchSpacing: {\n    label: 'Branch spacing',\n    shortId: 'bs',\n    type: 'number',\n    min: 1,\n    max: 10,\n  },\n  leafLength: {\n    label: 'Leaf length',\n    shortId: 'll',\n    type: 'number',\n    min: 5,\n    max: 20,\n    step: 5,\n  },\n  leafWidth: {\n    label: 'Leaf width',\n    shortId: 'lw',\n    type: 'number',\n    min: 4,\n    max: 20,\n  },\n} satisfies Params\n\nexport const presets: Presets<typeof parameters> = [\n  {\n    id: 'regular',\n    label: 'Regular',\n    values: {\n      treeHeight: 30,\n      branchSpacing: 3,\n      leafLength: 10,\n      leafWidth: 8,\n    },\n  },\n]\n\nexport const plugins: Plugins = ['smart-fasteners']\n\nexport const parts: PartsFn<typeof parameters> = (parameters) => {\n  const { treeHeight, branchSpacing, leafLength, leafWidth } = parameters\n\n  const numBranches = Math.floor((treeHeight - 2) / branchSpacing) - 1\n\n  return [\n    posts({ treeHeight }),\n    base({ leafLength, leafWidth }),\n    Array.from(Array(numBranches).keys()).map((branchIndex) =>\n      branch({ branchIndex, branchSpacing, leafLength, leafWidth }),\n    ),\n    top({ treeHeight, leafLength, leafWidth }),\n  ] satisfies Parts\n}\n\ntype PostOptions = {\n  treeHeight: number\n}\n\nfunction posts(options: PostOptions): Parts {\n  const { treeHeight } = options\n\n  return [\n    GridBeam.Z({\n      x: -1,\n      y: -1,\n      z: [0, treeHeight],\n    }),\n    GridBeam.Z({\n      x: 1,\n      y: -1,\n      z: [0, treeHeight],\n    }),\n    GridBeam.Z({\n      x: -1,\n      y: 1,\n      z: [0, treeHeight],\n    }),\n    GridBeam.Z({\n      x: 1,\n      y: 1,\n      z: [0, treeHeight],\n    }),\n  ]\n}\n\ntype BaseOptions = {\n  leafLength: number\n  leafWidth: number\n}\n\nfunction base(options: BaseOptions): Parts {\n  const { leafLength, leafWidth } = options\n\n  const baseLength = Math.ceil((leafLength + 3) / 5) * 5\n\n  return [\n    GridBeam.Y({\n      x: 0,\n      y: [-Math.floor((1 / 2) * baseLength), Math.ceil((1 / 2) * baseLength)],\n      z: 0,\n    }),\n    GridPanel.XY({\n      x: [-Math.floor((1 / 2) * leafWidth), Math.ceil((1 / 2) * leafWidth)],\n      y: [-2, -2 - leafLength],\n      z: 1,\n    }),\n\n    GridBeam.X({\n      x: [-Math.floor((1 / 2) * baseLength), Math.ceil((1 / 2) * baseLength)],\n      y: 0,\n      z: 1,\n    }),\n\n    GridBeam.Y({\n      x: -Math.floor((1 / 2) * baseLength),\n      y: [-2, 3],\n      z: 0,\n    }),\n    GridBeam.Z({\n      x: -Math.floor((1 / 2) * baseLength) + 1,\n      y: 1,\n      z: [0, 2],\n    }),\n    GridPanel.XY({\n      x: [-2, -2 - leafLength],\n      y: [-Math.floor((1 / 2) * leafWidth) + 1, Math.ceil((1 / 2) * leafWidth) + 1],\n      z: 2,\n    }),\n\n    GridBeam.Y({\n      x: Math.ceil((1 / 2) * baseLength) - 1,\n      y: [-2, 3],\n      z: 0,\n    }),\n    GridBeam.Z({\n      x: Math.floor((1 / 2) * baseLength) - 1,\n      y: 1,\n      z: [0, 2],\n    }),\n  ]\n}\n\ntype BranchOptions = {\n  branchIndex: number\n  branchSpacing: number\n  leafLength: number\n  leafWidth: number\n}\n\nfunction branch(options: BranchOptions): Parts {\n  const { branchIndex, branchSpacing, leafLength, leafWidth } = options\n\n  const branchLength = leafLength\n  const branchZ = 1 + (branchIndex + 1) * branchSpacing\n  const leafNudge = Math.floor((branchIndex + 2) / 4) % 2 === 0 ? 1 : 0\n\n  switch (branchIndex % 4) {\n    case 0:\n      return [\n        GridBeam.Y({\n          x: 0,\n          y: [-1, -1 + branchLength],\n          z: branchZ,\n        }),\n        GridPanel.XY({\n          x: [\n            -Math.floor((1 / 2) * leafWidth) + leafNudge,\n            Math.ceil((1 / 2) * leafWidth) + leafNudge,\n          ],\n          y: [2, 2 + leafLength],\n          z: branchZ + 1,\n        }),\n      ]\n    case 1:\n      return [\n        GridBeam.X({\n          x: [-1, -1 + branchLength],\n          y: 0,\n          z: branchZ,\n        }),\n        GridPanel.XY({\n          x: [2, 2 + leafLength],\n          y: [\n            -Math.floor((1 / 2) * leafWidth) - leafNudge + 1,\n            Math.ceil((1 / 2) * leafWidth) - leafNudge + 1,\n          ],\n          z: branchZ + 1,\n        }),\n      ]\n    case 2:\n      return [\n        GridBeam.Y({\n          x: 0,\n          y: [1, 1 - leafLength],\n          z: branchZ,\n        }),\n        GridPanel.XY({\n          x: [\n            -Math.floor((1 / 2) * leafWidth) - leafNudge + 1,\n            Math.ceil((1 / 2) * leafWidth) - leafNudge + 1,\n          ],\n          y: [-2, -2 - leafLength],\n          z: branchZ + 1,\n        }),\n      ]\n    case 3:\n      return [\n        GridBeam.X({\n          x: [1, 1 - branchLength],\n          y: 0,\n          z: branchZ,\n        }),\n        GridPanel.XY({\n          x: [-2, -2 - leafLength],\n          y: [\n            -Math.floor((1 / 2) * leafWidth) + leafNudge,\n            Math.ceil((1 / 2) * leafWidth) + leafNudge,\n          ],\n          z: branchZ + 1,\n        }),\n      ]\n    default:\n      return []\n  }\n}\n\ntype TopOptions = {\n  treeHeight: number\n  leafLength: number\n  leafWidth: number\n}\n\nfunction top(options: TopOptions): Parts {\n  const { treeHeight, leafLength, leafWidth } = options\n\n  return [\n    GridBeam.X({\n      x: [-Math.floor((1 / 2) * leafLength), Math.ceil((1 / 2) * leafLength)],\n      y: 0,\n      z: treeHeight - 1,\n    }),\n    GridPanel.XY({\n      x: [-Math.floor((1 / 2) * leafLength), Math.ceil((1 / 2) * leafLength)],\n      y: [-Math.floor((1 / 2) * leafWidth) + 1, Math.ceil((1 / 2) * leafWidth) + 1],\n      z: treeHeight,\n    }),\n  ]\n}\n",
