    code: "import type { Params, Parts, PartsFn, Plugins, Presets } from '@villagekit/design/kit'\nimport { GridBeam } from '@villagekit/part-gridbeam/creator'\nimport { GridPanel } from '@villagekit/part-gridpanel/creator'\n\nexport const parameters = {\n  width: {\n    label: 'Width',\n    shortId: 'w',\n    type: 'number',\n    min: 10,\n    max: 30,\n    step: 5,\n  },\n  depth: {\n    label: 'Depth',\n    shortId: 'd',\n    type: 'number',\n    min: 10,\n    max: 20,\n    step: 10,\n  },\n  workHeight: {\n    label: 'Work height',\n    shortId: 'wh',\n    type: 'number',\n    min: 8,\n    max: 30,\n  },\n  bottomShelfHeight: {\n    label: 'Bottom shelf height',\n    shortId: 'bsh',\n    type: 'number',\n    min: 2,\n    max: 30,\n  },\n  topShelfDepth: {\n    label: 'Top shelf depth',\n    shortId: 'tsd',\n    type: 'number',\n    min: 3,\n    max: 10,\n  },\n  topShelfHeight: {\n    label: 'Top shelf height',\n    shortId: 'tsh',\n    type: 'number',\n    min: 8,\n    max: 30,\n  },\n} satisfies Params\n\nexport const presets: Presets<typeof parameters> = [\n  {\n    id: 'default',\n    label: 'Default',\n    values: {\n      width: 30,\n      depth: 20,\n      workHeight: 23,\n      bottomShelfHeight: 4,\n      topShelfDepth: 8,\n      topShelfHeight: 30,\n    },\n  },\n]\n\nexport const parts: PartsFn<typeof parameters> = (parameters) => {\n  const { width, depth, workHeight, bottomShelfHeight, topShelfDepth, topShelfHeight } = parameters\n\n  return [\n    // front left z\n    GridBeam.Z({\n      x: 0,\n      y: 0,\n      z: [0, workHeight],\n    }),\n    // back left z\n    GridBeam.Z({\n      x: 0,\n      y: depth - 1,\n      z: [0, topShelfHeight],\n    }),\n    // front right z\n    GridBeam.Z({\n      x: width - 1,\n      y: 0,\n      z: [0, workHeight],\n    }),\n    // back right z\n    GridBeam.Z({\n      x: width - 1,\n      y: depth - 1,\n      z: [0, topShelfHeight],\n    }),\n\n    // bottom shelf left y\n    GridBeam.Y({\n      x: 1,\n      y: [0, depth],\n      z: bottomShelfHeight - 2,\n    }),\n    // bottom shelf right y\n    GridBeam.Y({\n      x: width - 2,\n      y: [0, depth],\n      z: bottomShelfHeight - 2,\n    }),\n    // bottom shelf front x\n    GridBeam.X({\n      x: [0, width],\n      y: 1,\n      z: bottomShelfHeight - 1,\n    }),\n    // bottom shelf back x\n    GridBeam.X({\n      x: [0, width],\n      y: depth - 2,\n      z: bottomShelfHeight - 1,\n    }),\n    // bottom shelf panel\n    GridPanel.XY({\n      x: [0, width],\n      y: [1, depth - 1],\n      z: bottomShelfHeight,\n    }),\n\n    // work left y\n    GridBeam.Y({\n      x: 1,\n      y: [0, depth],\n      z: workHeight - 2,\n    }),\n    // work right y\n    GridBeam.Y({\n      x: width - 2,\n      y: [0, depth],\n      z: workHeight - 2,\n    }),\n    // work front x\n    GridBeam.X({\n      x: [0, width],\n      y: 1,\n      z: workHeight - 1,\n    }),\n    // work back x\n    GridBeam.X({\n      x: [0, width],\n      y: depth - 2,\n      z: workHeight - 1,\n    }),\n    // work panel\n    GridPanel.XY({\n      x: [0, width],\n      y: [1, depth - 1],\n      z: workHeight,\n    }),\n\n    // top shelf back x\n    GridBeam.X({\n      x: [0, width],\n      y: depth - 2,\n      z: topShelfHeight - 2,\n    }),\n    // top shelf left y\n    GridBeam.Y({\n      x: 1,\n      y: [depth - 1, depth - 1 - topShelfDepth],\n      z: topShelfHeight - 1,\n    }),\n    // top shelf middle y\n    GridBeam.Y({\n      x: Math.floor(width / 2),\n      y: [depth - 1, depth - 1 - topShelfDepth],\n      z: topShelfHeight - 1,\n    }),\n    // top shelf right y\n    GridBeam.Y({\n      x: width - 2,\n      y: [depth - 1, depth - 1 - topShelfDepth],\n      z: topShelfHeight - 1,\n    }),\n    // top shelf panel\n    GridPanel.XY({\n      x: [0, width],\n      y: [depth - 1, depth - 1 - topShelfDepth],\n      z: topShelfHeight,\n    }),\n  ] satisfies Parts\n}\n\nexport const plugins: Plugins = ['smart-fasteners']\n",
