    code: "import type { Params, Parts, PartsFn, Plugins, Presets } from '@villagekit/design/kit'\nimport { GridBeam } from '@villagekit/part-gridbeam/creator'\n\nexport const parameters = {\n  width: {\n    label: 'Width',\n    shortId: 'w',\n    type: 'number',\n    min: 15,\n    max: 45,\n    step: 5,\n  },\n  height: {\n    label: 'Height',\n    shortId: 'h',\n    type: 'number',\n    min: 5,\n    max: 30,\n  },\n  shelfHeight: {\n    label: 'Shelf Height',\n    shortId: 'sh',\n    type: 'number',\n    min: 4,\n    max: 15,\n  },\n} satisfies Params\n\nexport const presets: Presets<typeof parameters> = [\n  {\n    id: 'regular',\n    label: 'Regular',\n    values: {\n      height: 15,\n      shelfHeight: 4,\n      width: 30,\n    },\n  },\n  {\n    id: 'short',\n    label: 'Short',\n    values: {\n      height: 5,\n      shelfHeight: 4,\n      width: 30,\n    },\n  },\n  {\n    id: 'tall',\n    label: 'Tall',\n    values: {\n      height: 25,\n      shelfHeight: 4,\n      width: 30,\n    },\n  },\n  {\n    id: 'narrow',\n    label: 'Narrow',\n    values: {\n      height: 15,\n      shelfHeight: 4,\n      width: 15,\n    },\n  },\n  {\n    id: 'wide',\n    label: 'Wide',\n    values: {\n      height: 15,\n      shelfHeight: 4,\n      width: 45,\n    },\n  },\n]\n\nexport const plugins: Plugins = ['smart-fasteners']\n\nexport const parts: PartsFn<typeof parameters> = (parameters) => {\n  const { width, height, shelfHeight } = parameters\n\n  const depth = 7\n\n  // 0-30 => 0, 31-45 => 2\n  const numLegSupports = Math.max(Math.ceil((width - 30) / 15), 0)\n\n  const numShelves = Math.max(Math.floor(height / shelfHeight), 1)\n\n  return [\n    GridBeam.Z({\n      x: 0,\n      y: 0,\n      z: [0, height],\n    }),\n    GridBeam.Z({\n      x: width - 1,\n      y: 0,\n      z: [0, height],\n    }),\n    GridBeam.Z({\n      x: 0,\n      y: depth - 1,\n      z: [0, height],\n    }),\n    GridBeam.Z({\n      x: width - 1,\n      y: depth - 1,\n      z: [0, height],\n    }),\n\n    range(numShelves).map((shelfIndex): Parts => {\n      const z = height - shelfIndex * (shelfHeight + 1) - 1\n\n      if (z < 1) {\n        return []\n      }\n\n      return [\n        GridBeam.X({\n          x: [0, width],\n          y: 1,\n          z,\n        }),\n        GridBeam.X({\n          x: [0, width],\n          y: 3,\n          z,\n        }),\n        GridBeam.X({\n          x: [0, width],\n          y: 5,\n          z,\n        }),\n\n        GridBeam.Y({\n          x: 1 + 0,\n          y: [0, depth],\n          z: z - 1,\n        }),\n        GridBeam.Y({\n          x: width - 2 - 0,\n          y: [0, depth],\n          z: z - 1,\n        }),\n      ]\n    }),\n\n    range(numLegSupports).map((legSupportIndex): Parts => {\n      const legSupportOffsetMultiplier = 1 / (numLegSupports + 1)\n      const legSupportOffset =\n        Math.round(legSupportOffsetMultiplier * width * (legSupportIndex + 1)) - 1\n      // nudge z posts towards the middle\n      const legZSupportXNudge = legSupportIndex >= Math.floor(numLegSupports / 2) ? -1 : 1\n\n      return [\n        range(numShelves).map((shelfIndex): Parts => {\n          const z = height - shelfIndex * (shelfHeight + 1) - 1\n\n          if (z < 1) {\n            return []\n          }\n\n          return [\n            GridBeam.Y({\n              x: legSupportOffset + legZSupportXNudge,\n              y: [0, depth],\n              z: z - 1,\n            }),\n          ]\n        }),\n\n        GridBeam.Z({\n          x: legSupportOffset,\n          y: 0,\n          z: [0, height],\n        }),\n        GridBeam.Z({\n          x: legSupportOffset,\n          y: depth - 1,\n          z: [0, height],\n        }),\n      ]\n    }),\n  ]\n}\n\nfunction range(end: number) {\n  return Array.from(Array(end).keys())\n}\n",
